  "title": "Kunbi Check Tile",
  "tile": {"width": 64, "height": 64, "wrap_x": true, "wrap_y": true},
  "palette": ["#B0282E", "#F3EEE3", "#1E1E1E", "#2F4A7A"],
  "background_index": 1,
  "layers": [
    {
      "id": "red_checks",
      "colour_index": 0,
      "anchor": [0, 0],
      "motifs": [
        {"kind": "rectangle", "center": [x, y], "size": [8, 8]}
